use strict;
use warnings;

# Entity types (persistent records)
my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare
  Reaction User UserIdentity UserSetting
);

# Collect all go files
open my $lf, "<", "/tmp/all_go.txt" or die $!;
my @files = <$lf>; chomp @files;
close $lf;

# Map file -> package dir
my %pkg_hits; # entity -> { pkgdir => 1 }
my %pkg_files; # pkgdir -> [files that hit]

for my $path (@files) {
  # skip proto generated
  next if $path =~ m{/proto/gen/};
  # skip data layer
  next if $path =~ m{/store/};

  open my $fh, "<", $path or die "$path: $!";
  my $text = do { local $/; <$fh> };
  close $fh;

  # package directory
  my $pkgdir = $path;
  $pkgdir =~ s{/[^/]+$}{};

  for my $e (@entities) {
    if ($text =~ /\bstore\.$e\b/) {
      $pkg_hits{$e}{$pkgdir} = 1;
    }
  }
}

print "=== Package counts (store.Type, excluding store/ and proto/gen) ===\n";
for my $e (sort { scalar(keys %{$pkg_hits{$b}}) <=> scalar(keys %{$pkg_hits{$a}}) || $a cmp $b } @entities) {
  my @pkgs = sort keys %{$pkg_hits{$e}||{}};
  printf "%-20s %d packages\n", $e, scalar(@pkgs);
  for my $p (@pkgs) {
    print "    $p\n";
  }
}
'

perl -e '
use strict;
use warnings;

my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare
  Reaction User UserIdentity UserSetting
);

open my $lf, "<", "/tmp/all_go.txt" or die $!;
my @files = <$lf>; chomp @files;
close $lf;

sub analyze {
  my ($label, $skip_test_files, $skip_store_all) = @_;
  my %pkg_hits;
  for my $path (@files) {
    next if $path =~ m{/proto/gen/};
    if ($skip_store_all) {
      next if $path =~ m{/store/};
    }
    next if $skip_test_files && $path =~ /_test\.go$/;

    open my $fh, "<", $path or die "$path: $!";
    my $text = do { local $/; <$fh> };
    close $fh;
    my $pkgdir = $path;
    $pkgdir =~ s{/[^/]+$}{};

    for my $e (@entities) {
      if ($text =~ /\bstore\.$e\b/) {
        $pkg_hits{$e}{$pkgdir} = 1;
      }
    }
  }
  print "=== $label ===\n";
  for my $e (sort { scalar(keys %{$pkg_hits{$b}||{}}) <=> scalar(keys %{$pkg_hits{$a}||{}}) || $a cmp $b } @entities) {
    my @pkgs = sort keys %{$pkg_hits{$e}||{}};
    printf "%-20s %d\n", $e, scalar(@pkgs);
    print "    $_\n" for @pkgs;
  }
  print "\n";
}

analyze("exclude store/, include tests", 0, 1);
analyze("exclude store/, exclude _test.go", 1, 1);
'
